"""The GraphRAG hasher module."""

import hashlib
from collections.abc import Callable
from typing import Any

import yaml

Hasher = Callable[[str], str]
"""Type alias for a hasher function (data: str) -> str."""


def sha256_hasher(data: str) -> str:
    """Generate a SHA-256 hash for the input data."""
    return hashlib.sha256(data.encode("utf-8")).hexdigest()


def make_yaml_serializable(data: Any, _seen: set[int] | None = None) -> Any:
    """Convert data to a YAML-serializable format, handling recursive containers."""
    if _seen is None:
        _seen = set()

    # Handle recursive references (e.g., self-referential dicts)
    if isinstance(data, (list, tuple, dict, set)):
        obj_id = id(data)
        if obj_id in _seen:
            return "<recursive>"
        _seen.add(obj_id)

    if isinstance(data, (list, tuple)):
        result = tuple(make_yaml_serializable(item, _seen) for item in data)
        _seen.discard(id(data))
        return result

    if isinstance(data, set):
        # Sort by the canonical string representation of elements to handle heterogeneous sets
        result = tuple(
            sorted((make_yaml_serializable(item, _seen) for item in data), key=str)
        )
        _seen.discard(id(data))
        return result

    if isinstance(data, dict):
        # Sort by the canonical string representation of the key to handle heterogeneous mapping keys
        result = tuple(
            sorted(
                ((str(key), make_yaml_serializable(value, _seen)) for key, value in data.items()),
                key=lambda item: item[0],
            )
        )
        _seen.discard(id(data))
        return result

    return str(data)


def _has_mixed_type_keys(data: Any, _seen: set[int] | None = None) -> bool:
    """Recursively detect any dict with keys of different types, with cycle awareness."""
    if _seen is None:
        _seen = set()

    if isinstance(data, dict):
        obj_id = id(data)
        if obj_id in _seen:
            return False
        _seen.add(obj_id)

        key_types = {type(key) for key in data}
        if len(key_types) > 1:
            return True

        for key, value in data.items():
            if _has_mixed_type_keys(value, _seen):
                return True

        _seen.discard(obj_id)
        return False

    if isinstance(data, (list, tuple, set)):
        obj_id = id(data)
        if obj_id in _seen:
            return False
        _seen.add(obj_id)
        for item in data:
            if _has_mixed_type_keys(item, _seen):
                return True
        _seen.discard(obj_id)
        return False

    return False


def hash_data(data: Any, *, hasher: Hasher | None = None) -> str:
    """Hash the input data dictionary using the specified hasher function.

    Args
    ----
        data: dict[str, Any]
            The input data to be hashed.
            The input data is serialized using yaml
            to support complex data structures such as classes and functions.
        hasher: Hasher | None (default: sha256_hasher)
            The hasher function to use. (data: str) -> str

    Returns
    -------
        str
            The resulting hash of the input data.

    """
    hasher = hasher or sha256_hasher
    if _has_mixed_type_keys(data):
        # Heterogeneous nested mapping keys cannot be canonicalized by yaml.dump(sort_keys=True);
        # use the cycle-safe canonical form that sorts by key string representation.
        return hasher(yaml.dump(make_yaml_serializable(data), sort_keys=True))
    try:
        return hasher(yaml.dump(data, sort_keys=True))
    except (TypeError, RecursionError):
        # Cyclic containers raise RecursionError from yaml.dump; fall back to canonical form
        return hasher(yaml.dump(make_yaml_serializable(data), sort_keys=True))
